    "說不定沒人知道，說不定可以拿去買那雙我一直想要的球鞋。"
    "我把皮夾握在手裡，手心開始出汗。\n"
    "車子快到站的時候，我看見前面一位阿姨一直低頭找東西，"
    "又把座位前後翻了一遍，急得臉都紅了。我站起來，把皮夾拿給司機。"
    "司機在廣播裡說有人撿到皮夾，請失主到前面來。\n"
    "阿姨走過來，一直向我鞠躬，還說要請我喝飲料。我擺手說不用，耳朵卻很燙。"
