_FENGZHENG_TEXT = (
    "那年夏天，爸爸帶我們去海邊放風箏。風箏是橘色的，上面印著一隻老鷹。"
    "我在沙灘上跑了很久，風箏總是剛飛起來就一頭栽進沙裡。"
    "爸爸走過來，把線交給我，要我不要一直跑，"
    "只要站著，感覺風拉線的時候就放一點。\n"
    "風箏慢慢飛上去了。線在手上一直抖，"
    "像有一隻看不見的手在跟我拔河。我抬頭看它，越飛越高，"
    "最後只剩下一個小小的橘點。\n"
    "就在那時候，線忽然斷了。風箏被風帶著往海的方向飛，"
    "飛得很穩，一點也不像剛才栽進沙裡的那一隻。我站在原地哭了。"
    "爸爸沒有安慰我，只說：「它飛走了，也去了它想去的地方。」\n"
    "後來我一直在想那句話。我慢慢明白，放手不是失去，"
    "有的東西本來就該飛在天空裡，而不是一直抓在手上。"
)

