_BEIYING_TEXT = (
    "我與父親已經兩年沒見面了，我最不能忘記的是他的背影。那年冬天，祖母去世了，父親也失業了，家裡的光景非常慘淡。"
    "辦完喪事後，父親要到南京找工作，我也要回北京念書，我們便同行。到了車站，父親因為事情忙，本來交代旅館熟識的服務員陪我去，"
    "但他終究不放心，決定親自送我。我當時二十歲，覺得自己已經是大孩子了，心裡還暗笑父親太瞎操心。上了火車，父親看著車外說："
    "「我去買幾個橘子，你就在這裡，不要走動。」要到對面月台買橘子，必須穿過鐵道，跳下去再爬上去。父親是個胖子，走起路來本來就很吃力。"
    "我看見他戴著黑布小帽，穿著深青色棉袍，步履蹣跚地走到鐵道邊。他穿過鐵道，要爬上對面月台時非常吃力：兩手攀著上面，"
    "兩腳向上縮，肥胖的身子微微向左傾斜，顯出很努力的樣子。這時我看見他的背影，我的眼淚很快地流了下來。等他抱著朱紅色的橘子走回來，"
    "把橘子散放在車廂地板上，撲撲身上的泥土，好像心裡鬆了一口氣。他要離開時，還回頭對我說：「進去吧，裡面無人。」"
    "直到他的背影消失在人群中，我的眼淚又流了下來。這些年來，父親和我到處奔波。如今他年紀大了，身體也不好。前陣子他在信中寫道："
    "「我身體平安，只是手臂痛得厲害，大概離開人世的日子不遠了吧。」讀到這裡，在晶瑩的淚光中，我又看見了那個肥胖、穿著青布棉袍的背影。"
    "唉！我不知道什麼時候才能再和他相見！"
)

