            title="媽媽的便當",
            author="",
            genre="記敘與抒情",
            text=(
                "我每天帶媽媽做的便當去學校。打開便當盒，有時是滷肉飯，有時是咖哩，"
                "還有切成小兔子形狀的蘋果。同學都羨慕我，說：「你媽媽好厲害。」"
                "有一次，我嫌便當菜色重複，對媽媽發了脾氣。媽媽沒說什麼，"
                "隔天便當裡多了一張小紙條，寫著：「今天試試看新的。」"
                "那是一道我從沒吃過的菜。我吃了一口，覺得好好吃。放學回家，我向媽媽道歉。"
                "她說：「我知道你不是故意的。」後來我每次打開便當，都會先看看有沒有紙條。"
                "媽媽的便當，不只是飯菜，也是她每天對我說的話。"
            ),
