                "看到忘記時間。管理員阿姨走過來，我以為她要趕我，她卻遞給我一張書籤，"
                "說：「這本書你看到第幾頁了？」我回答後，她微笑說：「慢慢看，書會等你。」"
                "從此，圖書館不只是借書的地方，而是我的避風港。當我心情不好，我就去那裡。"
                "書本不會問我怎麼了，卻總能給我答案。"
