            title="籃球場上的最後一秒",
            author="",
            genre="記敘與抒情",
            text=(
                "校際籃球賽冠軍戰，我們班落後兩分，只剩十秒。教練喊暫停，大家喘著氣。"
                "隊長說：「球給我，我來。」但教練卻看著我，說：「你跑位，有空檔就投。」"
                "我從未在關鍵時刻投籃，心跳快得像打鼓。哨聲響，隊長切入，引來兩人防守，"
                "他把球傳給我。我接到球，眼前只剩籃框。我深吸一口氣，出手。"
                "球在空中畫出弧線，刷網。比賽延長，最後我們贏了。"
                "隊友把我抬起來，我卻想起教練的話：「相信隊友，也要相信自己。」"
                "那一球，我投進的不只是分數，還有勇氣。"
            ),
