            text=(
                "冬至那天，天還沒亮，廚房就傳出搓湯圓的聲音。"
                "阿嬤把糯米粉倒進大盆，慢慢加水，一邊揉一邊說：「水要一點一點加，才不會太黏。」"
                "我負責把麵團搓成小圓球，一開始搓得大小不一，阿嬤說沒關係，煮起來一樣好吃。"
                "妹妹把一顆湯圓搓成三角形，大家笑了很久。"
                "晚上，一家人圍著桌子吃湯圓。爸爸說，吃一顆就長一歲。"
                "我問阿嬤為什麼要搓湯圓，她說以前的人希望全家團圓，湯圓圓圓的，就是這個意思。"
                "那年冬至很冷，可是廚房裡一直是熱的。"
            ),
