                "他的車後面綁著兩個大袋子，綠色制服被太陽晒得有點褪色。"
                "有一次下著大雨，我在門口等媽媽回來，看見他一手撐傘，一手護著信件。"
                "他把信塞進我家的信箱時，還特地用身體擋住雨。"
                "我問他為什麼不乾脆把信放著就好，他說：「信裡面可能是很重要的消息。」"
                "後來我搬家了。新家的信箱在社區大門旁，很少見到同一位郵差。"
                "可是每當我打開信箱，都會想起那個下雨天，和那串遠遠就聽得到的鈴聲。"
