                "有一次數學課，一隻麻雀飛進來，在教室上空繞了一圈。"
                "全班都笑了，老師也停下來等牠出去。"
                "等牠從另一扇窗飛走，老師說：「牠只是想找出口。」"
                "那天放學，我特別留下來看窗臺。"
                "原來牠們會撿地上掉落的餅乾屑，也會在樹上吵個不停。"
                "後來我才發現，不是牠們闖進我們的教室，"
                "而是我們的教室蓋在牠們原來的地方。"
