                "第一晚我寫了兩行，覺得很像流水帳。"
                "後來我發現，寫下來的事情會變得不一樣。"
                "有一次我和同學吵架，氣得寫了滿滿一頁，隔天再看，"
                "才發現自己其實也有不對的地方。我沒有把那一頁撕掉，因為那也是我的一部分。"
