                "我們慢慢往上走。霧裡聽得到水滴從葉子落下的聲音，也聽得到自己的呼吸。"
                "走了四十分鐘，忽然有一道光穿進來，霧像被誰從上面掀開，"
                "山谷出現在我們腳下。我愣在原地，什麼話都說不出來。"
                "下山時，爸爸說，如果一開始就回頭，就看不到剛才那一段了。"
