            title="一碗熱湯",
            author="",
            genre="記敘與抒情",
            text=(
                "月考前一天，我發燒了。喉嚨痛得吞不下東西，"
                "媽媽請了半天假在家陪我。她沒有多說什麼，只到廚房煮了一碗湯。"
                "湯很簡單：蛋花、一點蔥、幾片豆腐。她把碗放在我面前，說：「先喝一口，慢慢來。」"
                "我喝了一口，喉嚨還是痛，可是身體慢慢暖起來。"
                "那天下午我睡了一覺，醒來時看到媽媽坐在旁邊摺衣服，桌上放著一杯溫水。"
                "隔天我還是去考試了，成績普通。媽媽沒有問分數，只問我有沒有吃飽。"
                "後來我每次生病，都會想起那碗湯的味道。"
            ),
