                "同學拍手，我卻覺得耳朵很燙，不太敢抬頭。"
                "回家的路上我把獎狀捲起來，塞進書包最裡面。"
                "晚餐時媽媽問我考得怎樣，我說了。全家人都很高興，"
                "只有阿嬤問我：「你喜歡這次的準備過程嗎？」"
                "我愣了一下。老實說，考前那兩週我幾乎每天都熬夜，讀得很煩，一點也不喜歡。"
                "阿嬤說：「第一名很好，可是如果你下一次只想著不能輸，就會很累。」"
                "後來我把獎狀貼在書桌前。每次看到它，我都會先想一想，自己是為了什麼在讀。"
