                "那支鉛筆是我借他的，他卻弄丟了。我說他從來不珍惜別人的東西，他說我太小氣。"
                "接下來三天，我們誰也不理誰，下課各自走開。"
                "第四天下午，我在掃地時發現那支鉛筆卡在講桌底下。"
                "撿起來的時候，我忽然覺得很不好意思。"
                "放學時我追上阿宏，把鉛筆放在他手上，說：「找到了，是我錯怪你。」"
                "他愣了一下，然後從書包拿出一顆糖，說這本來是昨天要給我的。"
                "那天回家的路上，我一直在想：吵架的時候，我只記得自己生氣，卻忘了問清楚。"
