                "便當是媽媽早上做的，用布包著，打開時還是溫的。"
                "菜色很普通：滷蛋、豆干、一點青菜。爸爸總是把滷蛋夾給我，說他比較喜歡豆干。"
                "火車經過稻田的時候，爸爸會指著窗外說：「你看，那就是我們吃的米。」"
                "我看著一片一片往後退的綠色，覺得火車好像載著我們穿過一幅很長的畫。"
                "後來阿祖不在了，那條路線我們也很少再走。"
                "可是每次吃到滷蛋，我還是會想起那個便當的味道，和爸爸說的話。"
